CREATE TABLE public.samman_companies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, name text NOT NULL, registration_number text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (organization_id, name));
CREATE TABLE public.samman_clients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, name text NOT NULL, phone text, address text, kilometers_per_shipment numeric NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (organization_id, name));
CREATE TABLE public.samman_suppliers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, name text NOT NULL, phone text, address text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (organization_id, name));
CREATE TABLE public.samman_material_types (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (organization_id, name));
CREATE TABLE public.samman_drivers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, driver_name text NOT NULL, vehicle_number text, total_kilometers numeric NOT NULL DEFAULT 0, last_reset_date timestamptz, is_hidden boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (organization_id, driver_name));
CREATE TABLE public.samman_serial_numbers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, serial_code text NOT NULL CHECK (serial_code ~ '^\d{8}$'), status text NOT NULL DEFAULT 'available' CHECK (status IN ('available','used','cancelled')), used_at timestamptz, used_by_shipment_id uuid, created_by uuid, cancelled_at timestamptz, cancelled_by text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (organization_id, serial_code));
CREATE TABLE public.samman_shipments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL,
  document_number bigint GENERATED BY DEFAULT AS IDENTITY, print_number integer NOT NULL DEFAULT 0,
  company_id uuid REFERENCES public.samman_companies(id) ON DELETE SET NULL,
  client_id uuid REFERENCES public.samman_clients(id) ON DELETE SET NULL,
  supplier_id uuid REFERENCES public.samman_suppliers(id) ON DELETE SET NULL,
  material_type_id uuid REFERENCES public.samman_material_types(id) ON DELETE SET NULL,
  driver_id uuid REFERENCES public.samman_drivers(id) ON DELETE SET NULL,
  entry_date timestamptz NOT NULL DEFAULT now(), exit_date timestamptz, shipment_number text,
  empty_weight numeric NOT NULL DEFAULT 0, full_weight numeric NOT NULL DEFAULT 0,
  net_weight numeric GENERATED ALWAYS AS (full_weight - empty_weight) STORED,
  kilometers numeric NOT NULL DEFAULT 0,
  invoice_number text NOT NULL, invoice_value numeric NOT NULL DEFAULT 0,
  previous_serial_id uuid REFERENCES public.samman_serial_numbers(id) ON DELETE SET NULL,
  serial_id uuid REFERENCES public.samman_serial_numbers(id) ON DELETE SET NULL,
  pdf_path text, invoice_pdf_path text, drive_file_url text, drive_invoice_file_url text,
  driver_signature text, receiver_signature text, manager_signature text,
  created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (organization_id, invoice_number));
ALTER TABLE public.samman_serial_numbers ADD CONSTRAINT samman_serial_used_by_fk FOREIGN KEY (used_by_shipment_id) REFERENCES public.samman_shipments(id) ON DELETE SET NULL;
CREATE TABLE public.samman_employees (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, name text NOT NULL, residence_number text, profession text, salary numeric NOT NULL DEFAULT 0, start_date date, hourly_rate numeric GENERATED ALWAYS AS (salary / 30 / 10) STORED, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.samman_overtime_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, employee_id uuid NOT NULL REFERENCES public.samman_employees(id) ON DELETE CASCADE, record_date date NOT NULL DEFAULT current_date, hours numeric NOT NULL DEFAULT 0, hourly_rate numeric NOT NULL DEFAULT 0, total_amount numeric GENERATED ALWAYS AS (hours * hourly_rate) STORED, notes text, created_by uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.samman_activity_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, user_id uuid, username text, action text NOT NULL, description text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ON public.samman_shipments (organization_id, entry_date DESC);
CREATE INDEX ON public.samman_shipments (driver_id);
CREATE INDEX ON public.samman_shipments (client_id);
CREATE INDEX ON public.samman_overtime_records (employee_id, record_date);
CREATE TRIGGER samman_shipments_updated BEFORE UPDATE ON public.samman_shipments FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
DO $$ DECLARE t text; BEGIN
FOREACH t IN ARRAY ARRAY['samman_companies','samman_clients','samman_suppliers','samman_material_types','samman_drivers','samman_serial_numbers','samman_shipments','samman_employees','samman_overtime_records','samman_activity_logs'] LOOP
  EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', t);
  EXECUTE format('GRANT ALL ON public.%I TO service_role', t);
  EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
  EXECUTE format('CREATE POLICY "org members manage" ON public.%I FOR ALL TO authenticated USING (public.user_in_org(auth.uid(), organization_id)) WITH CHECK (public.user_in_org(auth.uid(), organization_id))', t);
END LOOP; END $$;